// Normaliza entrada: JSON o multipart/form-data
const input = $input.first();
let raw = input.json?.body ?? input.json ?? {};
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = {}; } }
const body = raw && typeof raw === 'object' ? raw : {};
const j = input.json || {};
const binary = input.binary || {};

let message = body.message ?? j.message ?? '';
let client_name = body.client_name ?? body.clientName ?? j.client_name ?? j.clientName ?? '';
let conversation_id = body.conversation_id ?? body.conversationId ?? j.conversation_id ?? j.conversationId ?? null;
let actIdVal = body.act_id ?? body.meta_ad_account_id ?? j.act_id ?? j.meta_ad_account_id ?? j.query?.act_id ?? null;
if (actIdVal && !String(actIdVal).startsWith('act_')) actIdVal = null;
let attachedImageBase64 = null;
let hasVideo = false;

if (binary.image) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'image');
    attachedImageBase64 = buffer.toString('base64');
  } catch (e) {
    message += ' [Error leyendo imagen adjunta: ' + e.message + ']';
  }
}
if (binary.video) hasVideo = true;

let contextAdd = '';
if (attachedImageBase64) contextAdd += ' [Usuario adjuntó imagen (base64 listo). Usar tool upload_ad_image con act_id y image_base64 antes de crear campaña.]';
if (hasVideo) contextAdd += ' [Usuario adjuntó vídeo. Para vídeos usar URL pública o upload_ad_image_from_url.]';

return {
  json: { message: message + contextAdd, client_name: String(client_name || '').trim(), conversation_id, attached_image_base64: attachedImageBase64, attached_video: hasVideo, act_id: actIdVal },
  binary: input.binary || {}
};

const input = $input.first().json;
const conversation_id = input.conversation_id || `meta-ads-${Date.now()}`;
return { json: { ...input, conversation_id } };

const item = $input.first();
const redisValue = item.json.value || item.json;
if (!redisValue) return [];
const client = typeof redisValue === 'string' ? JSON.parse(redisValue) : redisValue;
const prev = $('Asegurar conversation_id').first().json;
return {
  json: {
    ...prev,
    client_name: client.name,
    act_id: client.meta_ad_account_id,
    page_id: client.meta_page_id,
    from_cache: true
  }
};

const items = $input.all().map(i => i.json);
const listJson = JSON.stringify(items);
return { json: { listJson, _clients: items } };

const prev = $('Asegurar conversation_id').first().json;
const clients = $input.first().json._clients || JSON.parse($input.first().json.listJson || '[]');
const clientName = (prev.client_name || '').trim().toLowerCase();
const msg = (prev.message || '').toLowerCase();
let match = clients.find(c => {
  const n = (c.name || '').toLowerCase();
  return n && (n.includes(clientName) || clientName.includes(n) || msg.includes(n.split(' ')[0]));
});
if (!match && msg) {
  for (const c of clients) {
    const first = (c.name || '').split(' ')[0]?.toLowerCase();
    if (first && msg.includes(first)) { match = c; break; }
  }
}
if (!match) {
  return { json: { ...prev, act_id: null, page_id: null, error: 'Cliente no encontrado' } };
}
return {
  json: {
    ...prev,
    client_name: match.name,
    act_id: match.meta_ad_account_id,
    page_id: match.meta_page_id,
    from_cache: false
  }
};

const prev = $('Asegurar conversation_id').first().json;
const raw = $input.first().json.value;
let clients = [];
try {
  clients = typeof raw === 'string' ? (JSON.parse(raw || '[]') || []) : (Array.isArray(raw) ? raw : []);
} catch (e) {
  clients = [];
}
if (!Array.isArray(clients)) clients = [];
const clientName = (prev.client_name || '').trim().toLowerCase();
const msg = (prev.message || '').toLowerCase();
let match = clients.find(c => {
  const n = (c.name || '').toLowerCase();
  return n && (n.includes(clientName) || clientName.includes(n) || msg.includes((n.split(' ')[0] || '')));
});
if (!match && msg) {
  for (const c of clients) {
    const first = (c.name || '').split(' ')[0]?.toLowerCase();
    if (first && msg.includes(first)) { match = c; break; }
  }
}
if (!match) {
  return { json: { ...prev, act_id: null, page_id: null, error: 'Cliente no encontrado' } };
}
return {
  json: {
    ...prev,
    client_name: match.name,
    act_id: match.meta_ad_account_id,
    page_id: match.meta_page_id,
    from_cache: false
  }
};

const it = $input.first().json;
const aid = it.act_id && String(it.act_id).startsWith('act_') ? it.act_id : null;
let msg = it.message || '';
if (aid) msg = '[Contexto: act_id=' + aid + ', client_name=' + (it.client_name || '') + '] ' + msg;
return { json: { ...it, message: msg, act_id: aid } };
